"""One standalone results workspace: payload, figures and HTML are composed once."""
from __future__ import annotations
import csv
import html
import io
import json
import os
import tempfile
from pathlib import Path
from av_core import Seq,HSP,coverage_data,merge_intervals,msa_metrics,sequence_stats,sliding_scores
from av_display import figure_title
from av_figures import build_figures,MAX_DISTANCE_WORK
from av_tree import TREE_FIGURE,tree_svg
from av_units import units_for
from av_version import VERSION
