MAX_MSA_ROWS=1000
MAX_HSPS=2000
MAX_SEQUENCE_ROWS=5000


def comparison_context(settings,mode,query_ids,target_count):
    """Describe the exact local input roles without depending on live files."""
    query_path=settings.get('original_query') or settings.get('query') or ''
    target_path=settings.get('original_references') or settings.get('references') or ''
    if mode=='msa' and not target_path:return None
    return {'queryFile':Path(query_path).name if query_path else 'Query FASTA (name not recorded)',
            'queryPath':query_path,'queryIds':list(query_ids),
            'targetFile':Path(target_path).name if target_path else 'Target FASTA (name not recorded)',
            'targetPath':target_path,'targetCount':target_count,'method':mode.upper()}


def build_comparison_summary(out,batch,settings):
    """An honest group summary; scientific evidence stays in each query result."""
    out=Path(out);out.mkdir(parents=True,exist_ok=True)
    rows=[]
    for run in batch.get('runs',[]):
        values=(run['query_id'],run['status'].replace('_',' '),run.get('matches','—'),run.get('error',''))
        rows.append('<tr>'+''.join('<td>'+html.escape(str(value))+'</td>' for value in values)+'</tr>')
    context=comparison_context(settings,batch.get('mode',settings.get('mode','')),
        batch.get('query_ids') or [run['query_id'] for run in batch.get('runs',[])],batch.get('reference_count',0))
    inputs=''
    if context:
        esc=lambda value:html.escape(str(value))
        inputs=('<section aria-label="Comparison inputs"><h2>What was searched against what?</h2>'
            '<p><strong>Query sequences:</strong> '+esc(', '.join(context['queryIds']))+'<br>From: '+esc(context['queryFile'])+'</p>'
            '<p><strong>Searched against:</strong> '+esc(context['targetFile'])+' · '+esc(context['targetCount'])+' target sequences</p>'
            '<p><strong>Method:</strong> '+esc(context['method'])+' · supplied local FASTA targets</p>'
            '<details><summary>Input file paths</summary><pre>Query: '+esc(context['queryPath'] or 'Not recorded')+
            '\nTarget: '+esc(context['targetPath'] or 'Not recorded')+'</pre></details></section>')
    content='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>AlignView · Sequence matches</title><style>body{font:16px system-ui,sans-serif;max-width:1000px;margin:40px auto;padding:0 20px;color:#173247}table{width:100%;border-collapse:collapse}th,td{padding:12px;text-align:left;border-bottom:1px solid #dce5ea;overflow-wrap:anywhere}pre{white-space:pre-wrap;overflow-wrap:anywhere}p{line-height:1.6}</style>
<h1>Sequence matches</h1>'''+inputs+'''<p>Each query was compared independently against the same target dataset. Identity and coverage are not pooled across queries.</p>
<table><thead><tr><th>Query sequence</th><th>Status</th><th>Retained matches</th><th>Details</th></tr></thead><tbody>'''+''.join(rows)+'''</tbody></table>
<p>This file is a group summary. Open the saved AlignView project to inspect each query's complete evidence, or export its individual report.</p>
<details><summary>Recorded group settings</summary><pre>'''+html.escape(json.dumps({'comparison':batch,'settings':settings},ensure_ascii=False,indent=2))+'''</pre></details></html>'''
    target=out/'report.html'
    with tempfile.NamedTemporaryFile(mode='w',encoding='utf-8',dir=out,prefix='.report-',suffix='.html',delete=False) as stream:
        stream.write(content);temporary=Path(stream.name)
    temporary.replace(target)
    return target


def _json(value):
    return json.dumps(value,ensure_ascii=False,separators=(',',':'),allow_nan=False).replace('&','\\u0026').replace('<','\\u003c').replace('>','\\u003e').replace('\u2028','\\u2028').replace('\u2029','\\u2029')


def build_payload(query,ref_seqs,hsps,mode,settings,history,msa_seqs=None,dot=None,sha_query='',sha_refs=''):
    rows=coverage_data(hsps,len(query.seq),{r.id:len(r.seq) for r in ref_seqs})
    units=units_for(mode,sequence_stats(query)['kind'])
    records=[(query,'query'),*((record,'reference') for record in ref_seqs)]
    collision=any(record.id==query.id for record in ref_seqs)
    run=settings.get('calculation_runs',{}).get('msa',{})
    preparation=run.get('preparation',{}) if isinstance(run,dict) else {}
    preparation=preparation if isinstance(preparation,dict) else {}
    query_aliases=preparation.get('sequence_aliases',{})
    reference_aliases=preparation.get('reference_alignment_ids',{})
    query_aliases=query_aliases if isinstance(query_aliases,dict) else {}
    reference_aliases=reference_aliases if isinstance(reference_aliases,dict) else {}
    sources=[]
    for record,role in records:
        fallback=(('query:' if role=='query' else 'ref:')+record.id if collision and record.id==query.id else record.id)
        identifier=query_aliases.get('QUERY',fallback) if role=='query' else reference_aliases.get(record.id,fallback)
        sources.append({'id':record.id,'role':role,'msaId':identifier})
    msa={'seqs':[{'id':r.id,'seq':r.seq} for r in msa_seqs[:MAX_MSA_ROWS]],'metrics':msa_metrics(msa_seqs)} if msa_seqs else None
    return {'schema':1,'version':VERSION,'queryName':query.id,'queryLen':len(query.seq),'queryStats':sequence_stats(query),
        'referenceCount':len(ref_seqs),'mode':mode,'units':{'query':units.query,'subject':units.subject,'aligned':units.aligned,'msa':units.msa},
        'settings':settings,'comparisonContext':comparison_context(settings,mode,[query.id],len(ref_seqs)),
        'history':history,'coverage':rows,'combined':merge_intervals([h.qspan for h in hsps],len(query.seq)),
        'hsps':[h.record() for h in hsps[:MAX_HSPS]],'msa':msa,'dotplot':dot,
        'sequenceStats':[{**sequence_stats(r),'role':role} for r,role in records[:MAX_SEQUENCE_ROWS]],'alignmentSources':sources,'shaQuery':sha_query,'shaRefs':sha_refs,
        'limits':{'msaIncluded':len(msa['seqs']) if msa else 0,'msaTotal':len(msa_seqs or []),'hspsIncluded':min(MAX_HSPS,len(hsps)),
            'hspsTotal':len(hsps),'sequenceRowsIncluded':min(MAX_SEQUENCE_ROWS,len(records)),'sequenceRowsTotal':len(records)}}


def build_report(out:Path,query:Seq,ref_seqs:list[Seq],hsps:list[HSP],mode:str,settings:dict,
                 history:list,msa_seqs:list[Seq]|None=None,dot:dict|None=None,sha_query='',sha_refs='',motifs=None,orf_rows=None):
    out=Path(out);out.mkdir(parents=True,exist_ok=True)
    payload=build_payload(query,ref_seqs,hsps,mode,settings,history,msa_seqs,dot,sha_query,sha_refs)
    figures,metadata=build_figures(query,ref_seqs,hsps,msa_seqs,mode,motifs,orf_rows,payload['msa']['metrics'] if payload['msa'] else None)
    payload['analysisNotes']=['The automatic pairwise-distance figure was skipped for this alignment size. Calculate distances explicitly in the application when needed.'] if msa_seqs and len(msa_seqs)**2*len(msa_seqs[0].seq)>MAX_DISTANCE_WORK else []
    directory=out/'figures';directory.mkdir(exist_ok=True)
    (directory/(TREE_FIGURE+'.svg')).unlink(missing_ok=True)
    tree=out/'tree_fasttree.nwk';payload['treeError']=''
    if tree.is_file():
        try:
            figures[TREE_FIGURE]=tree_svg(tree.read_text(encoding='utf-8'))
            metadata[TREE_FIGURE]={'group':'Phylogeny','source':'FastTree','description':'Lengths use substitutions/site when available. Arbitrary drawing root. Local SH-like support is not bootstrap support.'}
        except (OSError,ValueError) as exc:payload['treeError']='Tree figure unavailable: '+str(exc)
    previous_catalog=out/'figures_catalog.tsv'
    if previous_catalog.is_file():
        with previous_catalog.open(encoding='utf-8',newline='') as stream:
            for row in csv.DictReader(stream,delimiter='\t'):
                old=(out/row.get('file','')).resolve()
                if old.parent==directory.resolve() and old.suffix=='.svg' and old.stem not in figures:
                    old.unlink(missing_ok=True)
    for key,svg in figures.items():(directory/(key+'.svg')).write_text(svg,encoding='utf-8')
    (out/'coverage.svg').write_text(coverage_svg(len(query.seq),payload['coverage'],payload['combined'],unit=payload['units']['query']),encoding='utf-8')
    metric='gc' if sequence_stats(query)['kind']=='DNA/RNA' else 'entropy';window=max(1,min(101,len(query.seq)))
    profile=plot_svg(sliding_scores(query.seq,window=window,step=max(1,window//4),kind=metric),title=f'{metric.upper()} profile · QUERY ({payload["units"]["query"]})',ylabel=metric)
    (out/'profile.svg').write_text(profile,encoding='utf-8');payload['profileSVG']=profile
    if msa_seqs:(out/'msa_conservation.svg').write_text(figures.get('09_conservation',''),encoding='utf-8')
    if dot:(out/'dotplot.svg').write_text(dotplot_svg(dot),encoding='utf-8')
    index=out/'vsearch/analyses.json';payload['vsearch']=json.loads(index.read_text(encoding='utf-8')) if index.is_file() else {}
    catalog=[]
    for key in figures:
        info=metadata[key];catalog.append({'file':f'figures/{key}.svg','category':info['group'],'description':info['description'],
            'query_unit':'NA' if key==TREE_FIGURE else payload['units']['query'],'subject_unit':'NA' if key==TREE_FIGURE else payload['units']['subject'],
            'alignment_unit':'NA' if key==TREE_FIGURE else payload['units']['aligned']})
    stream=io.StringIO();writer=csv.DictWriter(stream,fieldnames=['file','category','description','query_unit','subject_unit','alignment_unit'],delimiter='\t',lineterminator='\n');writer.writeheader();writer.writerows(catalog)
    (out/'figures_catalog.tsv').write_text(stream.getvalue(),encoding='utf-8');payload['figureCatalog']=catalog
    report=out/'report.html'
    markup=render_report(payload,figures,metadata)
    temporary=None
    try:
        with tempfile.NamedTemporaryFile(mode='w',encoding='utf-8',dir=out,prefix='.report-',suffix='.html',delete=False) as stream:
            temporary=Path(stream.name);stream.write(markup)
        os.replace(temporary,report)
    finally:
        if temporary:temporary.unlink(missing_ok=True)
    return report


