def _figure_cards(figures,metadata):
    cards=[]
    for key,svg in figures.items():
        info=metadata.get(key,{'group':'Other','description':''})
        cards.append('<article class="panel figcard" data-group="'+html.escape(info['group'],quote=True)+'" data-figure="'+html.escape(key,quote=True)+'">'
            +'<div class="row spread"><h2>'+html.escape(figure_title(svg,key))+'</h2><button class="downloadSvg" data-fig="'+html.escape(key,quote=True)+'">Download SVG</button></div>'
            +'<details class="figure-view"><summary>Open figure</summary><div class="figure-svg">'+svg+'</div></details><p class="hint">'+html.escape(info['description'])+'</p></article>')
    return ''.join(cards)


def _vsearch_cards(analyses):
    names={'search':'Global search','dereplicate':'Dereplication','cluster':'Clustering','chimeras':'Chimera screening'}
    cards=['<div class="notice">VSEARCH uses native nucleotide metrics. Global identity and qcov/tcov differ from local HSP metrics; BLAST E-values and bitscores are not calculated.</div>']
    for action,result in analyses.items():
        cards.append('<article class="panel"><h2>'+html.escape(names.get(action,action))+'</h2><div class="vsearch-summary">')
        for key,value in result.get('summary',{}).items():
            cards.append('<div><span class="hint">'+html.escape(key.replace('_',' '))+'</span><b>'+html.escape(str(value))+'</b></div>')
        cards.append('</div>');rows=result.get('preview',[])
        if rows:
            columns=list(rows[0]);cards.append('<div class="tablewrap"><table><thead><tr>'+''.join('<th>'+html.escape(key)+'</th>' for key in columns)+'</tr></thead><tbody>')
            for row in rows:cards.append('<tr>'+''.join('<td>'+html.escape(str(row.get(key,'')))+'</td>' for key in columns)+'</tr>')
            cards.append('</tbody></table></div>')
        else:cards.append('<p class="muted">No retained rows in this preview.</p>')
        cards.append('<p class="scope">Preview limited to 200 rows. Complete native files remain in the saved project.</p><details><summary>Executed tool and settings</summary><pre>'+html.escape(json.dumps({'settings':result.get('settings',{}),'commands':result.get('commands',[])},ensure_ascii=False,indent=2))+'</pre></details></article>')
    return ''.join(cards)

