def render_report(payload,figures=None,metadata=None):
    """Render trusted generated SVGs and safely embedded sequence/result data."""
    figures=figures or {};metadata=metadata or {}
    data=dict(payload);data.setdefault('version',VERSION);data.setdefault('vsearch',{});data.setdefault('settings',{});data.setdefault('history',[])
    categories=sorted({info.get('group','Other') for info in metadata.values()})
    options='<option value="">All categories</option>'+''.join('<option value="'+html.escape(x,quote=True)+'">'+html.escape(x)+'</option>' for x in categories)
    markup=_MARKUP.replace('__VERSION__',html.escape(str(data['version']))).replace('__TREE_KEY__',TREE_FIGURE).replace('__FIGURE_OPTIONS__',options).replace('__FIGURES__',_figure_cards(figures,metadata)).replace('__VSEARCH__',_vsearch_cards(data['vsearch']))
    script='const TREE_KEY='+_json(TREE_FIGURE)+';\n'+_SCRIPT
    return '<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AlignView · Results workspace</title><style>'+_STYLE+'</style></head><body>'+markup+'<script id="reportData" type="application/json">'+_json(data)+'</script><script>'+script+'</script></body></html>'
